{
  "scenes": [
    {
      "scene_id": "ep1-scene1",
      "lines": [
        {
          "line_id": "ep1-s1-l1",
          "kind": "action",
          "text": "刺耳的电火花“啪”声炸响，紧接着林岚迅速拉下沉重电闸的“咔哒”声，切断电源。",
          "audio_cue_ref": "sfx_spark_and_breaker"
        },
        {
          "line_id": "ep1-s1-l2",
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "哎！怎么又黑了？这广播刚说两句就断，街坊们还等着听呢！",
          "performance_hint": "语气急促带焦躁，后半句放缓显出对听众的挂念。哎字后留0.2秒气口，模拟视线骤然变暗的本能停顿"
        },
        {
          "line_id": "ep1-s1-l3",
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "别动，手电给我。",
          "performance_hint": "语速平稳干脆，不带情绪起伏，仅传递指令感。两词组之间微顿，模拟伸手接物的连贯动作节奏"
        },
        {
          "line_id": "ep1-s1-l4",
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "旧电源接头烧了，整个广播站彻底瘫痪。",
          "performance_hint": "咬字清晰偏冷，陈述事实时音量略降，不渲染恐慌。逗号处换气一次，保持胸腔共鸣稳定输出"
        },
        {
          "line_id": "ep1-s1-l5",
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "不能吧？昨天还好好的，是不是有人嫌吵，故意把线给剪了？",
          "performance_hint": "前半句迟疑上扬，后半句压低嗓音带出质疑与防备。不能吧后轻叹半秒，再切入猜测语气"
        },
        {
          "line_id": "ep1-s1-l6",
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "过来，一起核对下设备状态。拿万用表。",
          "performance_hint": "语速平稳，带有不容拒绝的专业感，引导对方靠近。句末无拖音，模拟工具交接时的利落收势"
        },
        {
          "line_id": "ep1-s1-l7",
          "kind": "action",
          "text": "万用表“滴滴”测电阻声。",
          "audio_cue_ref": "sfx_multimeter_beep"
        },
        {
          "line_id": "ep1-s1-l8",
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "你看，电阻无穷大。线没断，是接头老化进水短路。别瞎猜了，拿抹布来。",
          "performance_hint": "指着万用表屏幕，数据部分平稳客观，转折处加重语气打断对方思路，结尾恢复指令口吻。线没断后微顿0.3秒，制造逻辑转折的听觉焦点"
        }
      ]
    }
  ],
  "episode_summary": "广播站突发断电，林岚与周野在排查中确认是旧电源接头进水而非人为破坏。林岚主动让周野共同核对设备状态，用数据打消其猜疑。在清理积水与拆卸生锈接头的协作中，周野试图提及旧事被林岚以专业态度回避，但两人仍默契配合完成了初步维修。电源接通后，周野提议修好试音时敲三声铃报平安，但闪烁的灯光暗示隐患未除，约定悬而未决。",
  "fact_delta": [
    {
      "fact": "确认广播站断电原因是旧电源接头老化进水短路，排除人为剪线破坏。"
    },
    {
      "fact": "旧电源接头已被拆卸并更换为新接头，电源初步接通。"
    },
    {
      "fact": "推上电闸后指示灯亮起但随后闪烁，表明线路仍存在未排查出的隐患。"
    }
  ],
  "relationship_delta": [
    {
      "relationship": "林岚与周野",
      "change": "从开局周野的猜疑与林岚的防备，转变为林岚主动邀请周野共同核对设备状态，在物理协作中被迫靠近、互相配合，周野主动提出三声铃约定试图破冰，林岚虽未直接回应但未拒绝，关系初步松动。"
    }
  ],
  "new_open_threads": [
    "三声铃报平安",
    "灯光闪烁暗示的线路隐患"
  ],
  "closed_threads": []
}
